//! Probe (scratch worktree, never committed): does an app's onclick / ondoubleclick on an
//! `<object>` carrying a custom widget fire through the driver's `click`? What does the snapshot
//! read of that object? And what does today's Circle Drawer read at lint on its boot?

use std::sync::{Arc, Mutex};

use blitz_dom::Widget;
use blitz_test_harness::Harness;
use blitz_traits::events::UiEvent;
use dioxus::prelude::*;
use dioxus_native_dom::CustomWidgetAttr;
use escher_driver::Session;
use seven_guis::stand;
use seven_guis::tasks::timer::TimerTicks;

mod session_common;
use session_common::{click, lint, linted};

type Log = Arc<Mutex<Vec<&'static str>>>;

struct Heard(Log);

impl Widget for Heard {
    fn handle_event(&mut self, event: &UiEvent) {
        let word = match event {
            UiEvent::PointerDown(_) => "w-down",
            UiEvent::PointerUp(_) => "w-up",
            _ => return,
        };
        self.0.lock().unwrap().push(word);
    }
}

thread_local! {
    static WIDGET_LOG: std::cell::RefCell<Option<Log>> = const { std::cell::RefCell::new(None) };
}

#[component]
fn Probe() -> Element {
    let mut clicks = use_signal(|| 0u32);
    let mut dbl = use_signal(|| 0u32);
    let attr = use_hook(|| {
        let log: Log = Arc::new(Mutex::new(Vec::new()));
        WIDGET_LOG.with(|w| *w.borrow_mut() = Some(Arc::clone(&log)));
        CustomWidgetAttr::new(Heard(log))
    });
    rsx! {
        object {
            id: "probe-canvas",
            style: "display: block; width: 200px; height: 100px;",
            "data": attr,
            onclick: move |_| clicks += 1,
            ondoubleclick: move |_| dbl += 1,
        }
        p { id: "probe-clicks", "clicks {clicks} dbl {dbl}" }
    }
}

#[test]
fn probe_object_click() {
    for incremental in [false, true] {
        let mut session = Session::start("probe", || {
            stand::boot_alone(Probe, || (), stand::options(incremental))
        })
        .unwrap();
        let first = session.run(&click("probe-canvas"));
        let second = session.run(&click("probe-canvas"));
        let screen = session.harness().doc.snapshot();
        let text = screen.get("probe-clicks").map(|n| n.name.clone());
        let log = WIDGET_LOG.with(|w| w.borrow().as_ref().map(|l| l.lock().unwrap().clone()));
        let node = screen.get("probe-canvas").map(|n| format!("{n:?}"));
        eprintln!("PROBE incremental={incremental} first_ok={}", first.is_ok());
        eprintln!(
            "PROBE incremental={incremental} second_ok={}",
            second.is_ok()
        );
        eprintln!("PROBE incremental={incremental} text={text:?} widget={log:?}");
        eprintln!("PROBE incremental={incremental} node={node:?}");
        let findings = linted(&mut session, &lint());
        eprintln!("PROBE incremental={incremental} probe-lint={findings:?}");
        let unkeyed = session.harness().doc.unkeyed_actionable();
        eprintln!(
            "PROBE incremental={incremental} probe-unkeyed={}",
            unkeyed.len()
        );
    }
}

fn app_root() -> Element {
    use_hook(|| provide_context(TimerTicks::default()));
    seven_guis::app::app()
}

#[test]
fn probe_circle_drawer_today() {
    for incremental in [false, true] {
        let mut harness =
            Harness::from_vdom(VirtualDom::new(app_root), stand::options(incremental));
        let card = harness.node("#task-card-circle-drawer");
        harness.scroll_into_view(card);
        harness.click("#task-card-circle-drawer");
        let mut session = Session::start("circle-drawer", || harness).unwrap();
        let findings = linted(&mut session, &lint());
        eprintln!("PROBE incremental={incremental} cd-boot-lint={findings:?}");
        let unkeyed = session.harness().doc.unkeyed_actionable();
        eprintln!(
            "PROBE incremental={incremental} cd-unkeyed={}",
            unkeyed.len()
        );
        let screen = session.harness().doc.snapshot();
        let canvas = screen.get("circle-canvas").map(|n| format!("{n:?}"));
        eprintln!("PROBE incremental={incremental} cd-canvas={canvas:?}");
    }
}
